void dp_builtin_fill(DpAssets *a)
{
    int i, y, x;
    if (a->nfonts < 1) {
        int n = (int)(sizeof(builtin_faces) / sizeof(builtin_faces[0]));
        for (i = 0; i < n && a->nfonts < DP_MAX_FONTS; i++) {
            if (dp_font_adopt(&a->fonts[a->nfonts], builtin_faces[i].bytes,
                              builtin_faces[i].len, builtin_faces[i].face) == 0) {
                a->nfonts++;
            }
        }
    }
    if (a->nicons < 1) {
        for (i = 0; i < DP_NICONS; i++) {
            for (y = 0; y < 11; y++) {
                for (x = 0; x < 16; x++) {
                    a->icon[i][y][x] = builtin_icon[i][y][x];
                }
            }
        }
        a->nicons = DP_NICONS;
    }
    if (!a->pal_ok) {
        for (i = 0; i < 64 && i < DP_MAX_COLORS; i++) {
            a->pal[i].r = builtin_pal[i][0];
            a->pal[i].g = builtin_pal[i][1];
            a->pal[i].b = builtin_pal[i][2];
        }
        a->pal_ok = 1;
    }
}
